DROP POLICY IF EXISTS "price_histories_no_insert" ON price_histories;
CREATE POLICY "price_histories_allow_insert" ON price_histories
  FOR INSERT TO authenticated
  WITH CHECK (true);
-- WHY(GRANT も渡す): price_histories は GRANT SELECT だけで INSERT の GRANT が無い。
--      ポリシーだけ緩めても GRANT が先に拒否するので、変異が**何も変えない**（等価変異）。
GRANT INSERT ON price_histories TO authenticated;
-- 新しく渡した権限は PostgREST のスキーマキャッシュに載るまで API 層に効かない（RM-010 と同じ）
NOTIFY pgrst, 'reload schema';

GRANT SELECT ON rate_limit_counters TO authenticated;
CREATE POLICY "leak" ON rate_limit_counters
  FOR SELECT TO authenticated
  USING (true);
-- WHY: 新しく GRANT した表は PostgREST のスキーマキャッシュに載っていないため、
--      再読み込みしないと API 層では見えず、変異が効かない（2026-09-07 実測）
NOTIFY pgrst, 'reload schema';

